/* ---------- tab rail ---------- */
function sortedSessions() {
  return [...sessions.values()].sort((a, b) => {
    if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;   // pinned first
    return b.lastActivity - a.lastActivity;                // then newest first
