    .filter((c) => c.toLowerCase().includes(q))
    .sort((a, b) => {
      const as = a.toLowerCase().startsWith(q), bs = b.toLowerCase().startsWith(q);
      if (as !== bs) return as ? -1 : 1;          // prefix matches first
      return a.localeCompare(b);
