  slashItems.forEach((c, i) => {
    const row = el("div", "slash-item" + (i === slashIdx ? " sel" : ""));
    row.appendChild(el("span", "slash-name", "/" + esc(c)));
    row.addEventListener("mousedown", (e) => { e.preventDefault(); acceptSlash(i); });
