const LOCAL_COMMANDS = [{ name: "new", desc: "Start a new chat" }];
function handleLocalCommand(text) {
  const m = /^\/new(?:\s+([\s\S]*))?$/i.exec(text);
  if (!m) return false;
  const seed = (m[1] || "").trim();
