            continue
        sid = "i_" + info["uuid"]
        if sid in _sessions:
            continue
        _sessions[sid] = ClaudeSession(
            id=sid, title=info["title"], claude_session_id=info["uuid"],
            import_path=info["path"], last_activity=info["mtime"], autostart=False)
        _order.append(sid)
        added += 1
    if added:
        _save_meta()


def _periodic_save():
    while True:
        time.sleep(10)
        _save_meta()


_load_meta()
_import_existing()
quickaccess.load()
threading.Thread(target=_periodic_save, daemon=True).start()


