function usageText(r) {
  const u = r.usage || {};
  const cost = r.total_cost_usd != null ? "$" + r.total_cost_usd.toFixed(4) : "";
  const tok = u.output_tokens != null ? u.output_tokens + " out" : "";
  const ms = r.duration_ms ? (r.duration_ms / 1000).toFixed(1) + "s" : "";
  return [tok, ms, cost].filter(Boolean).join("  ·  ");
}

/* ---------- tab rail ---------- */
function sortedSessions() {
  return [...sessions.values()].sort((a, b) => {
    if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;   // pinned first
    return b.lastActivity - a.lastActivity;                // then newest first
  });
}
function renderTabs() {
  tabsEl.innerHTML = "";
  const list = sortedSessions();
  const anyPinned = list.some((s) => s.pinned);
  let section = null;   // which header we've emitted so far: "pinned" | "recent"
  list.forEach((s) => {
    if (anyPinned) {
      const want = s.pinned ? "pinned" : "recent";
      if (want !== section) {
        const h = el("div", "tabsection" + (s.pinned ? " pinned" : ""),
          s.pinned ? "◆ pinned" : "recent");
        tabsEl.appendChild(h);
        section = want;
      }
    }
    const t = el("div", "tab" + (s.id === activeId ? " active" : "") + (s.pinned ? " pinned" : ""));
    t.appendChild(el("span", "dot " + s.statusState));
    t.appendChild(el("span", "ttitle", esc(s.title)));
    const pin = el("span", "tpin" + (s.pinned ? " on" : ""), s.pinned ? "◆" : "◇");
    pin.title = s.pinned ? "Unpin" : "Pin";
    pin.addEventListener("click", (ev) => { ev.stopPropagation(); togglePin(s.id); });
    t.appendChild(pin);
    const x = el("span", "tclose", "×");
    x.title = "Close";
    x.addEventListener("click", (ev) => { ev.stopPropagation(); closeSession(s.id); });
    t.appendChild(x);
    t.addEventListener("click", () => switchTo(s.id));
    t.addEventListener("contextmenu", (ev) => { ev.preventDefault(); startRename(s, t); });
    t.addEventListener("dblclick", (ev) => { ev.preventDefault(); startRename(s, t); });
    tabsEl.appendChild(t);
  });
}
function startRename(s, t) {
  const span = t.querySelector(".ttitle");
  if (!span || t.querySelector(".trename")) return;   // already editing
  const inp = el("input", "trename");
  inp.value = s.title || "";
  span.replaceWith(inp);
  inp.focus();
  inp.select();
  let done = false;
  const finish = async (save) => {
    if (done) return;
    done = true;
    const v = inp.value.trim();
    if (save && v && v !== s.title) {
      s.title = v;
      try {
        await fetch("/sessions/" + s.id + "/title", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ title: v }),
        });
      } catch (_) {}
    }
    renderTabs();
  };
  inp.addEventListener("click", (e) => e.stopPropagation());
  inp.addEventListener("keydown", (e) => {
    e.stopPropagation();
    if (e.key === "Enter") { e.preventDefault(); finish(true); }
    else if (e.key === "Escape") { e.preventDefault(); finish(false); }
  });
  inp.addEventListener("blur", () => finish(true));
}
async function togglePin(id) {
  const s = sessions.get(id);
  if (!s) return;
  s.pinned = !s.pinned;
  renderTabs();
  try { await fetch("/sessions/" + id + "/pin", { method: "POST" }); } catch (_) {}
}
function switchTo(id) {
  const s = sessions.get(id);
  if (!s) return;
  activeId = id;
  sessions.forEach((x) => { x.logEl.hidden = x.id !== id; });
  // reflect this session into the top bar
  if (s.init) fillCaps(s.init); else { $("#model").textContent = "model —"; $("#perm").textContent = "perm —"; }
  applyStatus(s);
  setCtxBadge(s.ctxPct);
  $("#usage").textContent = s.lastUsage || "";
  renderTabs();
  s.scroll();
  input.focus();
}
async function createSession() {
  const r = await fetch("/sessions", { method: "POST" });
  const j = await r.json();
  const s = new Session(j.id, j.title);
  sessions.set(j.id, s);
  switchTo(j.id);
  return s;
}
async function closeSession(id) {
  const s = sessions.get(id);
  if (!s) return;
  await fetch("/sessions/" + id, { method: "DELETE" }).catch(() => {});
  s.destroy();
  sessions.delete(id);
  if (activeId === id) {
    const next = sortedSessions()[0];
    if (next) switchTo(next.id);
    else { activeId = null; createSession(); }
  } else {
    renderTabs();
  }
}

/* periodically refresh tab status dots */
setInterval(renderTabs, 1500);

/* ---------- usage badges (5h / 7d) ---------- */
function fmtReset(ts) {
  if (!ts) return "";
  const diff = ts - Math.floor(Date.now() / 1000);
  if (diff <= 0) return "now";
  if (diff < 3600) return "<1h";
  if (diff < 86400) return Math.floor(diff / 3600) + "h";
  return Math.ceil(diff / 86400) + "d";
}
async function pollUsage() {
  try {
    const u = await (await fetch("/usage")).json();
    const r5 = $("#r5h"), r7 = $("#r7d");
    if (!u.available) {
      r5.textContent = "5h —"; r7.textContent = "7d —";
      setUsageLevel(r5, null); setUsageLevel(r7, null);
      return;
    }
    const f = u.five_hour || {}, w = u.seven_day || {};
    r5.textContent = f.used_percentage != null
      ? `5h ${Math.round(f.used_percentage)}% · ${fmtReset(f.resets_at)}` : "5h —";
    r7.textContent = w.used_percentage != null
      ? `7d ${Math.round(w.used_percentage)}% · resets ${fmtReset(w.resets_at)}` : "7d —";
    setUsageLevel(r5, f.used_percentage);
    setUsageLevel(r7, w.used_percentage);
    const stale = u.age_seconds > 1800 ? ` (cache ${Math.round(u.age_seconds / 60)}m old)` : "";
    r5.title = "5-hour limit used" + stale;
    r7.title = "7-day limit used" + stale;
  } catch (_) {}
}
setInterval(pollUsage, 45000);
pollUsage();

/* ---------- boot greeting ---------- */
function bootGreeting() {
