  const finish = async (save) => {
    if (done) return;
    done = true;
    const v = inp.value.trim();
    if (save && v && v !== s.title) {
      s.title = v;
      try {
        await fetch("/sessions/" + s.id + "/title", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ title: v }),
        });
      } catch (_) {}
    }
    renaming = false;
    renderTabs();
  };
