function cronHint(cron) {
  const c = (cron || "").trim();
  if (!c) return "no schedule — enable + set a cron to run it automatically";
  const f = c.split(/\s+/);
  if (f.length !== 5) return "cron needs 5 fields: minute hour day month weekday";
  return "cron: " + c;
}
