  if (pct == null) return;                      // unknown → neutral default
  const lvl = pct >= 80 ? "lvl-crit" : pct >= 60 ? "lvl-warn" : "lvl-ok";
  elem.classList.add(lvl);
}
function setCtxBadge(pct, used, window) {
