/* ---------- per-chat scratchpad (queue notes to send later) ---------- */
function scratchKey(id) { return "mist-scratch:" + id; }
function loadScratch(id) {
  try { return JSON.parse(localStorage.getItem(scratchKey(id))) || []; }
  catch (_) { return []; }
}
function saveScratch(id, arr) {
  try {
    if (arr && arr.length) localStorage.setItem(scratchKey(id), JSON.stringify(arr));
    else localStorage.removeItem(scratchKey(id));
  } catch (_) {}
}
function updateScratchBadge() {
  const n = activeId ? loadScratch(activeId).length : 0;
  const b = $("#scratchBtn");
  b.textContent = n ? "note (" + n + ")" : "note";
  b.classList.toggle("has", n > 0);
}
function renderScratch() {
  const list = $("#scratchList");
  list.innerHTML = "";
  const items = activeId ? loadScratch(activeId) : [];
  if (!items.length) {
    list.appendChild(el("div", "scratch-empty", "Nothing queued for this chat yet."));
  } else {
    items.forEach((text, i) => {
      const row = el("div", "scratch-item");
      row.appendChild(el("div", "scratch-text", text));   // textContent — no HTML injection
      const send = el("button", "scratch-send", "send");
      send.title = "Send this note to the chat now";
      send.addEventListener("click", () => sendScratch(i));
      const del = el("button", "scratch-del", "×");
      del.title = "Discard this note";
      del.addEventListener("click", () => {
        const a = loadScratch(activeId); a.splice(i, 1); saveScratch(activeId, a); renderScratch();
      });
      row.appendChild(send);
      row.appendChild(del);
      list.appendChild(row);
    });
  }
  updateScratchBadge();
}
function addScratch() {
  if (!activeId) return;
  const ta = $("#scratchInput");
  const t = ta.value.trim();
  if (!t) return;
  const arr = loadScratch(activeId);
  arr.push(t);
  saveScratch(activeId, arr);
  ta.value = ""; ta.style.height = "auto";
  renderScratch();
  ta.focus();
}
function sendScratch(i) {
  if (!activeId) return;
  const arr = loadScratch(activeId);
  const text = arr[i];
  if (text == null) return;
  arr.splice(i, 1);
  saveScratch(activeId, arr);
  renderScratch();
  sessions.get(activeId).send(text);   // fires it as a normal message to this chat
}
$("#scratchBtn").addEventListener("click", () => {
  const p = $("#scratchpad");
  p.hidden = !p.hidden;
  if (!p.hidden) { renderScratch(); $("#scratchInput").focus(); }
});
$("#scratchClose").addEventListener("click", () => { $("#scratchpad").hidden = true; });
$("#scratchAdd").addEventListener("click", addScratch);
$("#scratchInput").addEventListener("input", () => {
  const ta = $("#scratchInput");
  ta.style.height = "auto";
  ta.style.height = Math.min(ta.scrollHeight, 120) + "px";
});
$("#scratchInput").addEventListener("keydown", (e) => {
  e.stopPropagation();
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); addScratch(); }
});

/* periodically refresh tab status dots */
setInterval(renderTabs, 1500);

